    glyph_framebuffer = _k.Attr(1114, 'glyph_framebuffer')
    icons = _k.Attr(1115, 'icons')
    line_length = _k.Attr(1116, 'line_length')
    mcu = _k.Attr(1117, 'mcu')
    printer = _k.Attr(1118, 'printer')
    spi = _k.Attr(1119, 'spi')
